/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

/** The education materials — GET /api/v1/education/materials (who may call: holders of education.give or education.manage or msds.view). */
export function listMaterials(query?: { include_inactive?: boolean }): Promise<MaterialOut[]> {
  return api<MaterialOut[]>("GET", withQuery(`/education/materials`, query), undefined);
}

/** Add a material — POST /api/v1/education/materials (who may call: holders of education.manage). */
export function addMaterial(body: MaterialIn): Promise<MaterialOut> {
  return api<MaterialOut>("POST", `/education/materials`, body, { idempotent: true });
}

/** Change or retire a material — PATCH /api/v1/education/materials/{material_id} (who may call: holders of education.manage). */
export function updateMaterial(material_id: number, body: MaterialUpdateIn): Promise<MaterialOut> {
  return api<MaterialOut>("PATCH", `/education/materials/${material_id}`, body);
}

/** The education register of a period — GET /api/v1/education/register (who may call: holders of education.manage or msds.view). */
export function registerEducation(query: { date_from: string; date_to: string; limit?: number; before_id?: number | null }): Promise<EducationOut[]> {
  return api<EducationOut[]>("GET", withQuery(`/education/register`, query), undefined);
}
